// 商圈 (business districts) for the map view: names and approximate outlines from
// data/districts.json, regenerated by scripts/build_districts.py. Static and public, so the
// response is cacheable for a day; no deal coordinates are involved here.
import type { Context } from "hono";
import data from "../data/districts.json";

export type District = {
  id: string;
  name: string;
  city: string;
  centre: [number, number]; // [lat, lng] WGS84
  radius_m: number;
  polygon: [number, number][]; // [[lat, lng], …], approximate (the source says 約為)
};

const body = {
  source: data.source,
  licence: data.licence,
  generated: data.generated,
  districts: (data.districts as unknown as District[]).map(({ id, name, city, centre, radius_m, polygon }) => ({
    id, name, city, centre, radius_m, polygon,
  })),
};

export function listDistricts(c: Context) {
  c.header("Cache-Control", "public, max-age=86400");
  return c.json(body);
}
